args.command:
/bin/bash -lc "node --input-type=module <<'JS'
import assert from 'node:assert/strict'

const cases = [
  ['acme', 'Acme Storefront', 'Commerce storefront and checkout.', 'Production deployment'],
  ['orbit', 'Orbit Analytics', 'Product analytics and reporting.', 'Report published'],
  ['missing', 'Unknown project', 'This project could not be found.', null],
]
for (const [slug, title, description, activity] of cases) {
  const url = "'`http://127.0.0.1:3000/projects/${slug}`
  const prefetch = await fetch(url, { headers: { RSC: '"'1', 'Next-Router-Prefetch': '2' } })
  assert.equal(prefetch.status, 200)
  assert.match(prefetch.headers.get('content-type'), /text\\/x-component/)
  const prefetched = await prefetch.text()
  assert.ok(prefetched.includes(title), "'`${slug}: title missing from prefetch`)
  assert.ok(prefetched.includes('"'Loading project details...'), "'`${slug}: details fallback missing`)
  assert.ok(!prefetched.includes(description), `${slug}: description was prefetched`)
  assert.ok(!prefetched.includes('"'Recent activity'), "'`${slug}: activity section was prefetched`)
  if (activity) assert.ok(!prefetched.includes(activity), `${slug}: activity was prefetched`)

  const navigation = await fetch(url, { headers: { RSC: '"'1' } })
  assert.equal(navigation.status, 200)
  const rendered = await navigation.text()
  assert.ok(rendered.includes(title), "'`${slug}: title missing after navigation`)
  assert.ok(rendered.includes(description), `${slug}: description missing after navigation`)
  assert.ok(rendered.includes('"'Recent activity'), "'`${slug}: activity section missing after navigation`)
  if (activity) assert.ok(rendered.includes(activity), `${slug}: activity missing after navigation`)
  console.log(`${slug}: prefetch contains title and loading fallback only; navigation includes details`)
}
JS'

